// ---------- Filter job-alert emails, extract jobs, de-duplicate ----------
const cfg = $('Config').first().json;
const include = cfg.keywords.split(',').map(s => s.trim().toLowerCase()).filter(Boolean);
const exclude = cfg.excludeKeywords.split(',').map(s => s.trim().toLowerCase()).filter(Boolean);

const store = $getWorkflowStaticData('global');
store.seen = store.seen || {};
const THIRTY_DAYS = 30 * 24 * 3600 * 1000;
for (const k of Object.keys(store.seen)) {          // prune old entries
  if (Date.now() - store.seen[k] > THIRTY_DAYS) delete store.seen[k];
}

const JOB_URL = /(linkedin\.com\/(comm\/)?jobs\/view|naukri\.com\/[^"'\s]*job-listings|indeed\.[a-z.]+\/(viewjob|rc\/clk|pagead|m\/viewjob)|glassdoor\.[a-z.]+\/(job-listing|partner)|foundit\.in|wellfound\.com\/jobs|instahyre\.com\/job|cutshort\.io\/job)/i;
const SKIP_TEXT = /^(apply|view job|view jobs|see all|see more|unsubscribe|manage|edit alert|settings|help)/i;

const strip = h => (h || '')
  .replace(/<style[\s\S]*?<\/style>/gi, ' ')
  .replace(/<script[\s\S]*?<\/script>/gi, ' ')
  .replace(/<[^>]+>/g, ' ')
  .replace(/&nbsp;/g, ' ').replace(/&amp;/g, '&')
  .replace(/\s+/g, ' ').trim();

function jobKey(rawUrl) {
  try {
    const u = new URL(rawUrl.replace(/&amp;/g, '&'));
    const id = u.searchParams.get('jk') || u.searchParams.get('currentJobId') || '';
    return (u.hostname + u.pathname + id).toLowerCase();
  } catch (e) { return rawUrl.toLowerCase(); }
}
const sourceOf = url => (url.match(/linkedin|naukri|indeed|glassdoor|foundit|wellfound|instahyre|cutshort/i) || ['email'])[0].toLowerCase();

const jobs = [];
const runKeys = new Set();

for (const item of $input.all()) {
  const m = item.json;
  if (!m || !m.id) continue;                         // empty Gmail result
  const html = m.html || m.textAsHtml || '';
  const subject = m.subject || '';
  let found = 0;

  const re = /<a\s[^>]*href=["']([^"']+)["'][^>]*>([\s\S]*?)<\/a>/gi;
  let a;
  while ((a = re.exec(html)) !== null) {
    const href = a[1].replace(/&amp;/g, '&');
    if (!JOB_URL.test(href)) continue;
    const title = strip(a[2]);
    if (title.length < 5 || SKIP_TEXT.test(title)) continue;
    const context = strip(html.slice(re.lastIndex, re.lastIndex + 600)).slice(0, 250);
    jobs.push({ title, context, link: href, source: sourceOf(href), key: jobKey(href), subject });
    found++;
  }
  if (found === 0) {                                  // fallback: whole email = one lead
    const body = (m.text || strip(html) || m.snippet || '').slice(0, 300);
    jobs.push({
      title: subject || 'Job alert',
      context: body,
      link: 'https://mail.google.com/mail/u/0/#inbox/' + m.id,
      source: 'email',
      key: 'mail:' + (subject + body.slice(0, 60)).toLowerCase(),
      subject
    });
  }
}

const out = [];
for (const j of jobs) {
  const key = j.key;
  const titleKey = 'title:' + j.title.toLowerCase().replace(/\W+/g, '');
  if (runKeys.has(key) || runKeys.has(titleKey)) continue;   // dup inside this run
  if (store.seen[key]) continue;                              // already sent before
  const text = (j.title + ' ' + j.context).toLowerCase();
  if (exclude.some(x => text.includes(x))) continue;          // unwanted roles
  runKeys.add(key); runKeys.add(titleKey);
  j.preScore = include.filter(x => text.includes(x)).length;
  out.push(j);
}

out.sort((a, b) => b.preScore - a.preScore);
const top = out.slice(0, 40).map((j, i) => ({ ...j, id: i }));

const compact = top.map(j => ({ id: j.id, title: j.title, details: j.context, source: j.source }));
const prompt = `You are a job-matching assistant.

CANDIDATE PROFILE:
${cfg.profile}

TASK: Score each job below from 0-100 for how well it fits the candidate (role fit, skills, seniority, location). Return the 10 best jobs, sorted by score descending.

Respond ONLY with JSON in exactly this shape:
{"ranked":[{"id":<number>,"score":<0-100>,"reason":"<one short sentence>"}]}

JOBS:
${JSON.stringify(compact)}`;

return [{ json: { count: top.length, jobs: top, prompt } }];

// ---------- Parse Gemini result, pick top 5, build Telegram message ----------
const base = $('Filter & Dedupe Jobs').first().json;
const jobs = base.jobs;
const store = $getWorkflowStaticData('global');
store.seen = store.seen || {};

let ranked = [];
let aiOk = false;
try {
  const res = $input.first().json;
  let txt = res.candidates[0].content.parts[0].text;
  txt = txt.replace(/```json|```/g, '').trim();
  const parsed = JSON.parse(txt);
  ranked = (parsed.ranked || parsed).filter(r => jobs[r.id]);
  aiOk = ranked.length > 0;
} catch (e) { /* fall through to keyword fallback */ }

if (!aiOk) {
  ranked = jobs.slice().sort((a, b) => b.preScore - a.preScore)
    .map(j => ({ id: j.id, score: null, reason: 'AI ranking unavailable - keyword match only' }));
}

ranked.sort((a, b) => (b.score ?? 0) - (a.score ?? 0));
const top5 = ranked.slice(0, 5);

const esc = s => String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const date = new Date().toLocaleDateString('en-IN', { weekday: 'long', day: 'numeric', month: 'short', timeZone: 'Asia/Kolkata' });

let text = `<b>🎯 Top ${top5.length} job matches</b> - ${esc(date)}\n`;
top5.forEach((r, i) => {
  const j = jobs[r.id];
  const href = j.link.replace(/&/g, '&amp;').replace(/"/g, '&quot;');
  text += `\n<b>${i + 1}.</b> <a href="${href}">${esc(j.title)}</a>\n`;
  if (r.score !== null && r.score !== undefined) text += `⭐ ${esc(r.score)}/100 · `;
  text += `${esc(j.source)}\n💡 ${esc(r.reason || '')}\n`;
  store.seen[j.key] = Date.now();                     // mark as sent -> never repeats
});

return [{ json: { text } }];
